(3, 'airtenam', 'Air Tenam merupakan sebuah desa yang terletak dalam (daerah) kecamatan Ulu Manna, Kabupaten Bengkulu Selatan, Provinsi Bengkulu, Indonesia.', '-4.259206', '103.057423', NULL, NULL, NULL, '2023-01-27 04:14:04', '2023-01-27 04:14:04'),
(4, 'guguk', 'Guguk terletak di kecamatan Renah Pembarap, kabupaten Merangin, Jambi.', '-2.174697', '102.076927', NULL, NULL, NULL, '2023-01-27 04:15:56', '2023-01-27 04:15:56'),
(5, 'KBKA', 'Kampung Baru Korong Nan Ampek terletak di kecamatan Koto XI Tarusan, Kebupaten Pesisir Selatan, Provinsi Sumatera Barat', '-1.086215', '100.489747', NULL, NULL, NULL, '2023-01-27 04:17:04', '2023-01-27 04:17:04'),
(6, 'laham', 'Laham adalah sebuah kecamatan di Kabupaten Mahakam Ulu, Provinsi Kalimantan Timur, Indonesia', '0.364163', '115.429295', NULL, NULL, NULL, '2023-01-27 04:17:04', '2023-01-27 04:17:04'),
(7, 'longlake', 'Long Lake adalah salah satu desa di kecamatan Malinau Selatan Hulu, Malinau, Kalimantan Utara, Indonesia.', '2.996309', '116.576058', NULL, NULL, NULL, '2023-01-27 04:17:48', '2023-01-27 04:17:48'),
(8, 'lunang', 'Lunang adalah sebuah kecamatan di Kabupaten Pesisir Selatan, provinsi Sumatra Barat, Indonesia', '-2.246385', '101.132209', NULL, NULL, NULL, '2023-01-27 04:17:48', '2023-01-27 04:17:48'),
(9, 'lunangtengah', 'Lunang Tengah adalah salah satu desa/kelurahan di Kecamatan Lunang, Kabupaten Pesisir Selatan, provinsi Sumatera Barat', '-2.218069', '101.118023', NULL, NULL, NULL, '2023-01-27 04:18:22', '2023-01-27 04:18:22'),
(10, 'pasiahlaweh', 'Nagari Pasia Laweh berada di Kecamatan Palupuh Kabupaten Agam Sumatera Barat', '-0.135141', '100.331153', NULL, NULL, NULL, '2023-01-27 04:18:22', '2023-01-27 04:18:22'),
(11, 'pondokparianlunang', 'Nagari pondok parian lunang Pondok Parian Lunang, Kecamatan Lunang', '-2.207707', '101.120401', NULL, NULL, NULL, '2023-01-27 04:20:23', '2023-01-27 04:20:23'),
(12, 'simanau', 'Simanau adalah sebuah nagari di Kecamatan Tigo Lurah, Kabupaten Solok, Sumatra Barat.', '-0.909835', '100.864188', NULL, NULL, NULL, '2023-01-27 04:20:23', '2023-01-27 04:20:23'),
(13, 'simancuang', 'Simancuang adalah sebuah jorong dari Nagari Alam Pauh Duo Kecamatan Pauh Duo Kabupaten Solok Selatan. Jorong ini popoler karena keberadaan hutan di sekitar perkampungan dan pengelolaan yang sarat dengan kearifan lokal sehingga menjadi  pelopor perhutanan sosial di Provinsi Sumatera Barat. Jorong ini berada dalam cekungan yang dipagari oleh Bukit Bariasan, dan masyarakat menjaga keberadaan hutan karena berperan penting dalam kegiatan pertanian mereka. Hutan sebagai sumber penampung air tentunya sangat dibutuhkan bagi kegiatan pertanian yang menjadi sumber penghidupan utama.', '-1.545762', '101.148588', NULL, NULL, NULL, '2023-01-27 04:20:52', '2023-01-27 04:20:52'),
(14, 'simarasok', 'Simarasok merupakan salah satu nagari yang terdapat dalam kecamatan Baso, Kabupaten Agam, Provinsi Sumatra Barat, Indonesia.\n\nNagari ini terletak kira kira 15 kilometer dari kota Bukittinggi, dan berada pada ketinggian kurang lebih 900 meter dari permukaan laut, kondisi geografisnya berbukit bukit,dan pada dataran rendahnya terdapat banyak areal persawahan.', '-0.244220', '100.484474', NULL, NULL, NULL, '2023-01-27 04:20:52', '2023-01-27 04:20:52'),
(15, 'sinarwajo', 'Sinar Wajo merupakan sebuah desa yang terletak dalam (daerah) kecamatan Mendahara Ulu, Kabupaten Tanjung Jabung Timur, Provinsi Jambi, Indonesia.', '-1.167243', '103.570299', NULL, NULL, NULL, '2023-01-27 04:21:47', '2023-01-27 04:21:47'),
(16, 'sirukam', 'Sirukam adalah sebuah nagari yang terletak di kecamatan Payung Sekaki, Solok, Sumatra Barat, Indonesia. Nama nagari ini diyakini berasal dari kata \"suruakkan\" (sembunyikan).', '-0.886402', '100.767987', NULL, NULL, NULL, '2023-01-27 04:21:47', '2023-01-27 04:21:47'),
(17, 'sumpurkudus', 'Sumpur Kudus adalah sebuah Kecamatan di Kabupaten Sijunjung, Sumatra Barat, Indonesia.', '-0.424235', '100.920501', NULL, NULL, NULL, '2023-01-27 04:22:36', '2023-01-27 04:22:36'),
(18, 'sungaibuluh', 'Sungai Buluh merupakan nagari paling timur dalam kecamatan Batang Anai, Kabupaten Padang Pariaman, Provinsi Sumatra Barat, Indonesia.', '-0.737221', '100.340501', NULL, NULL, NULL, '2023-01-27 04:22:36', '2023-01-27 04:22:36'),
(19, 'tigokotosilungkang', 'Tigo Koto Silungkang merupakan desa yang memiliki bentang alam pertanian padi dengan sawah terasering, udara sejuk,berada didataran tinggi dan juga memiliki ekosistem karst,terdapat beberapa goa karst dengan keunikan speleothems beragam yang sudah terbentuk ratusan juta tahun yang lalu,beberapa kegiatan geowisata sudah dikembangkan diantranya tracking,susur goa,camping,dan aktivitas geowisata lainnya yang dikelola dan dikembangkan oleh POKDARWIS', '-0.134941', '100.141448', NULL, NULL, NULL, '2023-01-27 04:23:37', '2023-01-27 04:23:37');
