INSERT INTO `guestbook` (`id`, `tanggal`, `nama`, `email`, `alamat`, `komentar`, `member`, `adminnya`) VALUES
(4, '2014-12-19', 'sayaculun7', 'n1cedream@outlook.com', '', 'tolong diperbaiki kesalahan website anda, \r\n\r\nhubungi saya untuk mengetahui kesalahan fatal nya 08562878886\r\n\r\n', 0, 1),
(6, '2015-05-29', 'ines', 'inesszahrina@gmail.com', 'Lampung', 'saya tertarik untuk ikut program pohon asuh. namun saya bingung, ada beberapa status pohon yang \'dipesan\' dan \'diadopsi\' apa beda keduanya ? terimakasih..', 0, 0),
(9, '2015-11-29', 'Veronika BiegunovÃ¡ ', 'verca.biegunova@seznam.cz', 'Czech Republic , 27.dubna 216, , Dobroslavice 74794', 'Hello , \r\nI want to ask you how I can adopt tree . I hope you manage to save forest . \r\nHave a nice day . Veronika BiegunovÃ¡ , Czech Republic\r\n', 0, 0),
(10, '2015-11-29', 'Peter Palffy', 'sari.pp@gmail.com', 'London, UK', 'Hi there,\r\nAfter a call from my friend I have decided to pay a donation of $20.00 to support your local community people. Even I have registration link in my email box, the PayPal account does not accept any payment to your gmail account. Please send my a correct PayPal account where I can transfer the money to. \r\nKind regards\r\nPeter Palffy', 0, 0),
(11, '2015-12-01', 'Radka', 'severka13@seznam.cz', 'MilÃ­n 365, 262 31 MilÃ­n, ÄŒR', 'ProsÃ­m zaslat informace o adopci stromu v ÄŒeskÃ©m jazyce. PÅ™edem dÄ›kuji\r\n<br><br>\r\nSilakan kirim informasi tentang adopsi pohon dalam bahasa Ceko. Terima kasih sebelumnya', 0, 0),
(12, '2015-12-03', 'Veronika Wevhal', 'vvondrakova@gmail.com', '', 'Hello, I would like to adopt tree and wanna pay it via PayPal but its not working. It is some few days problem or will not be possible to pay it via PayPal? Many thaks for your answer Veronika', 0, 0),
(13, '2015-12-22', 'Dominik ÄŒernÃ½', 'robincerny@seznam.cz', 'Czech republic', 'Hello, I have a problem with a payment. I wanted to send a donation, but it doesnÂ´t work. I want to pay only through PayPal.    Thank you, for answer.', 0, 0),
(17, '2016-05-31', 'lady syafitri', 'lady.soori25@gmail.com', '', 'Bagaimana cara mengadopsi pohon dengan cara berdonasi? thanks', 0, 0),
(19, '2016-06-15', 'Rifky', 'koerniawan@gmail.com', 'Jakarta', 'Dear Tim Pohon Asuh,\r\n\r\nKonfirmasi pembayaran adopsi 2 pohon No. A036 dan A037 atas nama Agus Triatmoko dan Bahari melalui Bank Mandiri sebesar masing-masing IDR 250K, terima kasih.\r\n\r\nSekiranya akan dikirimkan sertifikat, mohon untuk mengirimkan ke:\r\n\r\nPT. Saipem Indonesia\r\nGedung Alamanda Lt. 3\r\nJl. TB. Simatupang Kav. 23 - 24\r\nCilandak - Jakarta Selatan\r\n12430\r\n\r\nTerima kasih,\r\nRifky', 0, 0),
(20, '2016-07-22', 'reno rois', 'renorois07@gmail.com', '', 'Saya ingin mendonasikan sebagian uang hasil penjualan merchandise band saya ke hutan indonesia. Contact kemana ya ? Trims', 0, 0),
(21, '2016-09-20', 'Dr. Sunarti', 'snarti@unja.ac.id', 'CoE WAHYD Universitas Jambi', 'Saya bermakdud adopsi salah satu pohon di HA Rt. Kermas. Bagaimana caranya? Mohon informasinya.', 0, 0),
(23, '2016-10-26', 'Yustine HENDRIKA', 'yustinehendrika@gmail.com', 'Sorogatan 19 LGH 1401', 'halo,\r\nsaya sudah transfer via paypal untuk adopsi pohon atas nama Yustine Hendrika.\r\nTerima kasih.semoga bermanfaat', 0, 0),
(35, '2018-04-07', 'Sania Lorison', 'sania.lorison@gmail.com', '-', 'hi\r\n\r\nwe can help your website to get on first page of Google and increase the number of leads and sales you are getting from your website please email us back for full proposal\r\nbest regards\r\n\r\nSania', 0, 1),
(36, '2018-05-19', 'Antonius Djoko Nugroho', 'gonzo.antonius@gmail.com', '-', 'Mohon info beberapa waktu yl sy sdh transfer ke rekening BNI anda utk 1 pohon asuh, apakah sdh ada follow upnya?\r\nSalam lestari', 0, 1391),
(44, '2020-02-05', 'Viyanthi Silvana Kosasih', 'viyanthi.silvana@frieslandcampina.com', NULL, 'Dear Pohonasuh.org,\r\n\r\nperusahaan kami bermaksud untuk mengadakan program POHON ASUH untuk para karyawannya.\r\napakah ada program yang dapat kami pelajari untuk mencari insight dari pohonasuh.org?\r\n\r\nterima kasih,\r\nVivi', 0, 0),
(45, '2020-12-01', 'Heri Santiko', 'heri.santiko@sinarmas-agri.com', NULL, 'Dear KKI WARSI,\r\n\r\nSaya mau tanya bagaimana ikut berkontribusi dalam pohon asuh?\r\nSaya sedang mencoba eksplor terkait pohon asuh ada beberapa pertanyaan:\r\n1. Apakah jika satu account bisa memberikan gift ke banyak orang? Jika bisa bagaimana caranya? saya coba tetapi nama email yang saya add member tidak masuk dalam list.\r\n2. Maksimal per account dalam satu pembelian apa quatitinya max. 5?\r\n\r\nTerima kasih', 2161, 0);
